import { test, expect } from '@playwright/test';

test.describe('Card Payment Flow', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
  });

  test('should successfully complete a purchase with valid card details', async ({ page }) => {
    // Intercept the payment API call
    await page.route('**/api/payments/process', (route) => {
      route.continue();
    });

    // Locate and fill card number input using getByLabel
    const cardNumberInput = page.getByLabel('Card Number');
    await cardNumberInput.fill('4111111111111111');

    // Locate and fill expiry date input using getByLabel
    const expiryDateInput = page.getByLabel('Expiry Date');
    await expiryDateInput.fill('12/25');

    // Locate and fill CVV input using getByLabel
    const cvvInput = page.getByLabel('CVV');
    await cvvInput.fill('123');

    // Locate and fill cardholder name input using getByLabel
    const cardholderNameInput = page.getByLabel('Cardholder Name');
    await cardholderNameInput.fill('John Doe');

    // Locate and click the submit button using getByRole
    const submitButton = page.getByRole('button', { name: /pay/i });
    await submitButton.click();

    // Wait for payment processing
    await page.waitForResponse(response =>
      response.url().includes('/api/payments/process') && response.status() === 200
    );

    // Verify success message appears
    const successMessage = page.getByText('Payment successful');
    await expect(successMessage).toBeVisible();

    // Verify order confirmation details are displayed
    const orderId = page.getByText(/Order #/);
    await expect(orderId).toBeVisible();

    // Verify user is redirected to confirmation page
    await expect(page).toHaveURL(/.*\/order\/\d+/);
  });

  test('should display error message when card details are invalid', async ({ page }) => {
    // Intercept the payment API call and simulate failure
    await page.route('**/api/payments/process', (route) => {
      route.abort('failed');
    });

    // Locate and fill card number input using getByLabel
    const cardNumberInput = page.getByLabel('Card Number');
    await cardNumberInput.fill('1111');

    // Locate and fill expiry date input using getByLabel
    const expiryDateInput = page.getByLabel('Expiry Date');
    await expiryDateInput.fill('12/25');

    // Locate and fill CVV input using getByLabel
    const cvvInput = page.getByLabel('CVV');
    await cvvInput.fill('123');

    // Locate and fill cardholder name input using getByLabel
    const cardholderNameInput = page.getByLabel('Cardholder Name');
    await cardholderNameInput.fill('John Doe');

    // Locate and click the submit button using getByRole
    const submitButton = page.getByRole('button', { name: /pay/i });
    await submitButton.click();

    // Wait for error response
    await page.waitForResponse(response =>
      response.url().includes('/api/payments/process') && response.status() === 402
    );

    // Verify error message is displayed
    const errorMessage = page.getByText(/Invalid card details/i);
    await expect(errorMessage).toBeVisible();

    // Verify error details are shown
    const errorDetails = page.getByText(/Please check your card number or expiry date/i);
    await expect(errorDetails).toBeVisible();

    // Verify user remains on checkout page
    await expect(page).toHaveURL(/.*\/checkout/);
  });
});
